            + $"FootSlip L/R={telemetry.LeftFootSlipMeters:F3}/{telemetry.RightFootSlipMeters:F3}m, "
            + $"PelvisRange={telemetry.PelvisVerticalRangeMeters:F3}m, Limit={pelvisLimit:F3}m"
    });
