        private void Test_ShieldAbsorption()
        {
            var ctx = new DamageContext
            {
                BaseDamage       = 100f,
                TargetArmorType  = ArmorType.Unarmored,
                TargetCurrentHp  = 200f,
                TargetMaxHp      = 200f,
                TargetShieldHp   = 60f,
