        }

        private void Test_LifestealCalculation()
        {
            var ctx = new DamageContext
            {
                BaseDamage      = 100f,
                TargetArmorType = ArmorType.Unarmored,
                TargetCurrentHp = 500f,
                TargetMaxHp     = 500f,
